// View mode, sort, and search coordination for EAV record lists
// Tracks current state and updates HTMX URLs dynamically
// FTS search requires minimum 3 characters
document.addEventListener('DOMContentLoaded', function () {
    var buttons = document.querySelectorAll('.view-mode-btn');
    var sortSelect = document.getElementById('sort');
    var searchInput = document.getElementById('search');
    var form = document.getElementById('search-form');

    if (!form) return;

    var recordsUrl = form.dataset.recordsUrl;
    if (!recordsUrl) return;

    var MIN_SEARCH_LENGTH = 3;

    // Get current sort value from select
    function getCurrentSort() {
        return sortSelect ? sortSelect.value : 'updated_desc';
    }

    // Get current search query from input (only if >= MIN_SEARCH_LENGTH chars)
    function getCurrentQuery() {
        if (!searchInput) return '';
        var value = searchInput.value.trim();
        // Return query only if empty (reset) or >= MIN_SEARCH_LENGTH
        if (value.length === 0 || value.length >= MIN_SEARCH_LENGTH) {
            return value;
        }
        return ''; // Don't search for 1-2 char queries
    }

    // Get current view mode from active button
    function getCurrentView() {
        var view = 'list';
        buttons.forEach(function (btn) {
            if (btn.classList.contains('active')) {
                view = btn.dataset.viewMode;
            }
        });
        return view;
    }

    // Build URL with all current parameters
    function buildUrl(view) {
        var url = recordsUrl + '/partial?view=' + view;
        var sort = getCurrentSort();
        var query = getCurrentQuery();

        url += '&sort=' + encodeURIComponent(sort);
        if (query) {
            url += '&q=' + encodeURIComponent(query);
        }
        return url;
    }

    // Update all view mode buttons with current sort and query
    function updateButtonsHtmx() {
        buttons.forEach(function (btn) {
            var view = btn.dataset.viewMode;
            btn.setAttribute('hx-get', buildUrl(view));
            if (window.htmx) {
                htmx.process(btn);
            }
        });
    }

    // Update sort select with current view
    function updateSortHtmx() {
        if (!sortSelect) return;
        var view = getCurrentView();
        sortSelect.setAttribute('hx-get', recordsUrl + '/partial?view=' + view);
        sortSelect.setAttribute('hx-target', '#records-container');
        sortSelect.setAttribute('hx-trigger', 'change');
        sortSelect.setAttribute('hx-include', 'closest form');
        if (window.htmx) {
            htmx.process(sortSelect);
        }
    }

    // Update search input HTMX attributes
    function updateSearchHtmx() {
        if (!searchInput) return;
        var view = getCurrentView();
        searchInput.setAttribute('hx-get', recordsUrl + '/partial?view=' + view);
        searchInput.setAttribute('hx-target', '#records-container');
        // Only use input trigger with delay, not 'search' (which fires on Enter)
        searchInput.setAttribute('hx-trigger', 'input changed delay:300ms');
        searchInput.setAttribute('hx-include', 'closest form');
        if (window.htmx) {
            htmx.process(searchInput);
        }
    }

    // Handle Enter key manually to respect min length validation
    if (searchInput) {
        searchInput.addEventListener('keydown', function (evt) {
            if (evt.key === 'Enter') {
                evt.preventDefault();
                var value = searchInput.value.trim();
                // Only trigger search if empty (reset) or >= MIN_SEARCH_LENGTH
                if (value.length === 0 || value.length >= MIN_SEARCH_LENGTH) {
                    htmx.trigger(searchInput, 'input');
                }
            }
        });
    }

    // Block HTMX requests from search input when query is 1-2 chars
    if (searchInput) {
        searchInput.addEventListener('htmx:beforeRequest', function (evt) {
            var value = searchInput.value.trim();
            // Allow if empty (reset) or >= MIN_SEARCH_LENGTH
            if (value.length > 0 && value.length < MIN_SEARCH_LENGTH) {
                evt.preventDefault();
            }
        });
    }

    // Handle view mode button clicks
    buttons.forEach(function (btn) {
        btn.addEventListener('click', function () {
            buttons.forEach(function (b) { b.classList.remove('active'); });
            btn.classList.add('active');
            updateSortHtmx();
            updateSearchHtmx();
        });
    });

    // Handle sort select changes - update button URLs
    if (sortSelect) {
        sortSelect.addEventListener('change', function () {
            updateButtonsHtmx();
        });
    }

    // Handle search input changes - update button URLs
    if (searchInput) {
        searchInput.addEventListener('input', function () {
            updateButtonsHtmx();
        });
    }

    // Initialize on page load
    updateButtonsHtmx();
    updateSortHtmx();
    updateSearchHtmx();
});
